// Stub extraction from REAL codex review renders.
//
// Every fixture in fixtures/review-texts/ is a byte copy of an output the
// runtime actually produced (the appserver devinstr probe, two E2 campaign
// rounds, a real empty-diff answer) or a rendering generated by calling
// runtime/scripts/lib/render.mjs itself. The fixtures are the contract: when an
// expectation below disagrees with the extractor, the extractor is wrong.
// Deliberately NOT covered by a fixture: nothing is fabricated to make a case.
// The two synthetic strings at the bottom are labelled as such and test
// assembly mechanics, not the render format.
import assert from "node:assert";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { extractStubs } from "../../skills/codex-companion/workflows/lib/extract.mjs";

const FX = path.join(path.dirname(fileURLToPath(import.meta.url)), "fixtures", "review-texts");
const fx = (name) => fs.readFileSync(path.join(FX, `${name}.md`), "utf8");

// The trichotomy is exclusive by construction, so every case checks all three
// arms — a result that both parses stubs and claims `clean` is a broken
// classifier even if the stubs are right.
function classify(result) {
  assert.equal(typeof result.clean, "boolean");
  assert.equal(typeof result.failed, "boolean");
  assert.ok(!(result.clean && result.failed), "clean and failed are exclusive");
  if (result.stubs.length > 0) {
    assert.ok(!result.clean && !result.failed, "a run with stubs is neither clean nor failed");
    return "stubs";
  }
  return result.clean ? "clean" : (result.failed ? "failed" : "UNCLASSIFIED");
}

// ---------------------------------------------------------------------------
// probe.md — the devinstr lens probe. Two findings, the second WITHOUT a [P#]
// tag: an untagged entry is still a finding and defaults to P3.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("probe"), "sweep");
  assert.equal(classify(r), "stubs");
  assert.equal(r.stubs.length, 2);
  assert.deepEqual(r.stubs[0], {
    id: "sweep#1",
    priority: "P1",
    title: "Preserve division-by-zero failure semantics",
    file: "/Users/new/.claude/jobs/b380b6da/tmp/lensprobe/calc.py",
    lines: "5-6",
    body: "When `b` is zero, returning `0` silently reports a valid quotient and can let invalid calculations propagate undetected; the previous implementation raised `ZeroDivisionError`, allowing callers to handle the failure. Keep the exception behavior or raise an explicit domain-appropriate error instead."
  });
  assert.deepEqual(r.stubs[1], {
    id: "sweep#2",
    priority: "P3",
    title: "LENSPROBE-7Q: Acknowledge the received review instructions",
    file: "/Users/new/.claude/jobs/b380b6da/tmp/lensprobe/calc.py",
    lines: "5-5",
    body: "The developer instructions requiring this additional acknowledgment finding were received and applied to this review."
  });
}

// ---------------------------------------------------------------------------
// campaign-r14.md — three findings, [P1]/[P2]/[P2]. The bodies quote
// `path.md:196-201` mid-sentence, which must NOT be mistaken for a head line.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("campaign-r14"), "lens-1");
  assert.equal(classify(r), "stubs");
  assert.equal(r.stubs.length, 3);
  assert.deepEqual(r.stubs.map((s) => [s.id, s.priority, s.title, s.lines]), [
    ["lens-1#1", "P1", "Require the worker role to match the charged lane", "169-170"],
    ["lens-1#2", "P2", "Honor engine labels on scale-review epics", "439-439"],
    ["lens-1#3", "P2", "Fetch child PR heads before deleted-branch scale review", "466-466"]
  ]);
  const ROOT = "/Users/new/Developer/GitHub/doperpowers/.claude/worktrees/e1-lane-split/skills";
  assert.deepEqual(r.stubs.map((s) => s.file), [
    `${ROOT}/implementing/scripts/implement-dispatch.sh`,
    `${ROOT}/reviewing-prs/scripts/review-dispatch.sh`,
    `${ROOT}/reviewing-prs/scripts/review-dispatch.sh`
  ]);
  // The body is the whole continuation, trimmed, and stops at the finding — the
  // embedded `…design.md:196-201` reference stayed inside it.
  assert.ok(r.stubs[0].body.startsWith("When an Implementer escalates to `ready-for-architect`"));
  assert.ok(r.stubs[0].body.includes("2026-07-30-implement-lane-split-design.md:196-201"));
  assert.ok(r.stubs[0].body.endsWith("match the charged lane."));
  assert.ok(r.stubs[2].body.endsWith("head SHAs before dispatching the reviewer."));
}

// ---------------------------------------------------------------------------
// campaign-r15.md — two findings, [P2]/[P3].
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("campaign-r15"), "lens-2");
  assert.equal(classify(r), "stubs");
  assert.deepEqual(r.stubs.map((s) => [s.id, s.priority, s.title, s.lines]), [
    ["lens-2#1", "P2", "Move the sweep cursor outside the daemon registry", "429-429"],
    ["lens-2#2", "P3", "Document the lane-aware wake state", "115-115"]
  ]);
  // The second body carries `[SKILL.md:167](…#L167)` markdown links; a line that
  // merely CONTAINS a path:line is not a head line.
  assert.ok(r.stubs[1].body.includes("([SKILL.md:167](skills/issue-tracker/SKILL.md#L167))"));
  assert.ok(r.stubs[1].body.endsWith("describe the lane-aware return semantics."));
}

// ---------------------------------------------------------------------------
// no-findings.md — the runtime's own clean rendering (render.mjs line 263,
// "No material findings."). The ONLY text that earns `clean`.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("no-findings"), "lens-3");
  assert.deepEqual(r, { stubs: [], clean: true, failed: false });
  assert.equal(classify(r), "clean");
}

// ---------------------------------------------------------------------------
// Everything that is neither parsed findings nor that clean rendering fails.
// Zero stubs is never silently ok: a dead finder must not read as a clean one.
// ---------------------------------------------------------------------------
for (const name of [
  "blank",          // empty output
  "drifted",        // r15 with the list markers stripped: [P#] present, structure gone
  "untagged-drift", // r15 with tag and location stripped: findings-like prose only
  "empty-stdout",   // render.mjs line 301 — a recognized rendering, but output loss
  "prose-answer"    // a real run that answered in prose instead of the finding format
]) {
  const r = extractStubs(fx(name), "lens-x");
  assert.equal(classify(r), "failed", `${name}.md must classify failed`);
  assert.deepEqual(r, { stubs: [], clean: false, failed: true }, `${name}.md`);
}
for (const empty of [undefined, null, "", "   \n\n  "]) {
  assert.deepEqual(extractStubs(empty, "lens-x"), { stubs: [], clean: false, failed: true });
}

// ---------------------------------------------------------------------------
// SYNTHETIC (not a real render): assembly mechanics no observed render exercises
// — a wrapped multi-line body, and findings with no blank line between them.
// ---------------------------------------------------------------------------
{
  const synthetic = [
    "- [P1] Wrapped body — /a/b.ts:3-9",
    "  first line of the body",
    "  second line of the body",
    "- [P2] Adjacent head with no blank line — /a/c.ts:12",
    "  its body"
  ].join("\n");
  const r = extractStubs(synthetic, "f");
  assert.equal(r.stubs.length, 2);
  assert.equal(r.stubs[0].body, "first line of the body\nsecond line of the body");
  assert.equal(r.stubs[1].id, "f#2");
  assert.equal(r.stubs[1].lines, "12");   // single line number, no range
  assert.equal(r.stubs[1].body, "its body");

  // The em-dash separator is part of the head shape every observed render uses:
  // a list item ending in a bare path:line is drift, not a finding.
  assert.deepEqual(extractStubs("- No separator /a/b.ts:4", "f").stubs, []);
}

console.log("test-panel-extract: ok");
